BEGIN;

COMMENT ON TABLE optimat.portal_accounts IS 'Portal user accounts. Passwords are stored as salted scrypt hashes, never as plaintext.';
COMMENT ON COLUMN optimat.portal_accounts.id IS 'Unique account identifier generated as a UUID.';
COMMENT ON COLUMN optimat.portal_accounts.username IS 'Unique lowercase login name, containing 3 to 80 supported characters.';
COMMENT ON COLUMN optimat.portal_accounts.display_name IS 'Human-readable account name shown in the portal and account management screens.';
COMMENT ON COLUMN optimat.portal_accounts.password_hash IS 'Salted password hash in scrypt:salt:hash format. Generated by the application password utility.';
COMMENT ON COLUMN optimat.portal_accounts.role IS 'Account role: super_admin can manage all providers and accounts; provider can manage only explicitly assigned providers.';
COMMENT ON COLUMN optimat.portal_accounts.active IS 'Whether the account may authenticate and use existing sessions. False disables access.';
COMMENT ON COLUMN optimat.portal_accounts.created_at IS 'Timestamp when the account was created, stored with time zone.';

COMMENT ON TABLE optimat.portal_account_providers IS 'Many-to-many mapping of provider accounts to the providers they are allowed to manage. Super administrators do not require assignments.';
COMMENT ON COLUMN optimat.portal_account_providers.account_id IS 'Account receiving management permission. References portal_accounts.id.';
COMMENT ON COLUMN optimat.portal_account_providers.provider_id IS 'Existing provider that the account may manage. References providers.provider_id, not providers.id.';

COMMENT ON TABLE optimat.portal_sessions IS 'Revocable portal login sessions. Only token hashes are stored; raw bearer tokens are returned to the client at login.';
COMMENT ON COLUMN optimat.portal_sessions.token_hash IS 'SHA-256 hash of the random session bearer token. Used to look up and revoke a session.';
COMMENT ON COLUMN optimat.portal_sessions.account_id IS 'Account authenticated by this session. References portal_accounts.id.';
COMMENT ON COLUMN optimat.portal_sessions.expires_at IS 'Absolute expiration timestamp. Sessions are issued with an eight-hour lifetime and are rejected after expiry.';

COMMENT ON TABLE optimat.portal_login_limits IS 'Shared login attempt counters used to throttle authentication requests across application instances.';
COMMENT ON COLUMN optimat.portal_login_limits.key IS 'SHA-256 hash of a prefixed source IP address or normalized username used as the rate-limit key.';
COMMENT ON COLUMN optimat.portal_login_limits.attempts IS 'Number of login attempts counted in the current rate-limit window.';
COMMENT ON COLUMN optimat.portal_login_limits.resets_at IS 'Expiration timestamp of the current rate-limit window; a later attempt starts a new window.';

COMMIT;
